/// Final price in cents after the quantity discount.
pub fn final_price(unit_cents: u32, qty: u32) -> u32 {
    let percent = match qty {
        q if q >= 100 => 20,
        q if q >= 50 => 10,
        q if q >= 10 => 5,
        _ => 0,
    };
    let gross = unit_cents * qty;
    gross - gross * percent / 100
}

