test_setup_files.tests/discount_test.rs:
use disc::checkout::final_price;
use disc::quote::discount_percent;

#[test]
fn quote_discount_tiers() {
    assert_eq!(discount_percent(9), 0);
    assert_eq!(discount_percent(10), 5);
    assert_eq!(discount_percent(49), 5);
    assert_eq!(discount_percent(50), 10);
    assert_eq!(discount_percent(99), 10);
    assert_eq!(discount_percent(100), 20);
}

#[test]
fn checkout_applies_discount() {
    assert_eq!(final_price(100, 9), 900); // 0% off 900
    assert_eq!(final_price(100, 50), 4500); // 10% off 5000
    assert_eq!(final_price(100, 100), 8000); // 20% off 10000
}

#[test]
fn services_agree_at_boundaries() {
    assert_eq!(discount_percent(50), 10);
    assert_eq!(discount_percent(100), 20);
}

